function gm_add_item(actor, rewards)
    local rewardsMap = string.toIntIntMap(rewards, "#", "|")
    -- 添加奖励到背包
    additemmaptobag(actor, rewardsMap)
    info(actor, "gm 添加道具", actor, rewards)
end

function gm_last_lua(actor)
    gameDebug.print(actor, "gm_last_lua")
    local lastLuaMessage = getplaydef(actor, "J$gm_last_lua")
    if lastLuaMessage == nil then
        return
    end
    gameDebug.print(actor, "再次执行最后一次消息", lastLuaMessage, lastLuaMessage.uid, lastLuaMessage.msgID, lastLuaMessage.msgData)
    handlerequest(actor, lastLuaMessage.uid, lastLuaMessage.msgID, lastLuaMessage.msgData)
end